# bash completion for func. Generated by `func completions bash`.
# Install: add `eval "$(func completions bash)"` to ~/.bashrc

_func_scripts() { func list --names 2>/dev/null; }

_func_complete_scripts() {
    COMPREPLY=( $(compgen -W "$(_func_scripts)" -- "$cur") )
}

_func_files() {
    COMPREPLY=( $(compgen -f -- "$cur") )
}

# Where a script is expected: saved scripts and .rs files, never every file.
# Once the word looks like a path (./x, ../x, dir/x), offer directories to walk through, and .rs files.
_func_complete_scripts_or_files() {
    local IFS=$'\n'
    if [[ $cur == */* || $cur == .* ]]; then
        COMPREPLY=( $(compgen -d -S / -- "$cur") $(compgen -f -X '!*.rs' -- "$cur") )
        type compopt &>/dev/null && compopt -o nospace
    else
        COMPREPLY=( $(compgen -W "$(_func_scripts)" -- "$cur") $(compgen -f -X '!*.rs' -- "$cur") )
    fi
    return 0 # "no match" must stay "no match", never fall back to listing every file
}

# Completes flags when the word being typed starts with "-". Succeeds if it did.
_func_flags() {
    [[ $cur == -* ]] || return 1
    COMPREPLY=( $(compgen -W "$1" -- "$cur") )
}

_func() {
    local cur=${COMP_WORDS[COMP_CWORD]} cmd=${COMP_WORDS[1]} i positional=0
    COMPREPLY=()

    if (( COMP_CWORD == 1 )); then
        COMPREPLY=( $(compgen -W "edit run test check eval install list show path rename remove clean completions help" -- "$cur") )
        return
    fi

    for (( i = 2; i < COMP_CWORD; i++ )); do
        [[ ${COMP_WORDS[i]} == -* ]] || (( positional++ ))
    done

    case $cmd in
        edit|new|e) _func_flags '' || (( positional == 0 )) && _func_complete_scripts ;;
        run|r) _func_flags '-r --release' || { (( positional == 0 )) && _func_complete_scripts_or_files || _func_files; } ;;
        test|t) _func_flags '' || { (( positional == 0 )) && _func_complete_scripts_or_files || _func_files; } ;;
        check) _func_flags '' || { (( positional == 0 )) && _func_complete_scripts_or_files || _func_files; } ;;
        eval) _func_flags '-r --release' ;;
        install) _func_flags '-f --force' || { (( positional == 0 )) && _func_complete_scripts_or_files || _func_files; } ;;
        list|ls) _func_flags '--names' ;;
        show|cat) _func_flags '' || (( positional == 0 )) && _func_complete_scripts ;;
        path) _func_flags '' || (( positional == 0 )) && _func_complete_scripts ;;
        rename|mv) _func_flags '' || (( positional == 0 )) && _func_complete_scripts ;;
        remove|rm) _func_flags '-y --yes' || _func_complete_scripts ;;
        clean) _func_flags '' ;;
        completions) (( positional == 0 )) && COMPREPLY=( $(compgen -W "bash zsh fish" -- "$cur") ) ;;
        help) (( positional == 0 )) && COMPREPLY=( $(compgen -W "edit run test check eval install list show path rename remove clean completions help" -- "$cur") ) ;;
        *) ;;
    esac

    # After a script name the arguments are the script's: use normal file completion.
    if (( positional > 0 )) && [[ $cmd == @(run|r|test|t) ]]; then
        type compopt &>/dev/null && compopt -o default
    fi
}

complete -F _func func
